/* e-AKHA Timecard Rebuild April 2026 — BY NAME ONLY
   Source: APRIL 2026.pdf extracted by ChatGPT
   IMPORTANT: Matching ignores Department because department in timecard may be wrong.
   Use inside live e-AKHA page: upload this file to repo then run:
   fetch('tc_rebuild_by_name_april2026.js?v='+Date.now()).then(r=>r.text()).then(eval)
*/
(function(){
'use strict';
var PATCH='TC_REBUILD_BY_NAME_APRIL_2026_v1';
var B64='';
function decode(){var bin=atob(B64);var bytes=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return JSON.parse(new TextDecoder('utf-8').decode(bytes));}
var TC_DATA=decode();
window.TC_REBUILD_APRIL_2026_BY_NAME=TC_DATA;
function U(v){return String(v==null?'':v).toUpperCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/MOHAMMAD|MUHAMMAD|MOHAMED|MOHAMMAAD/g,'MOHAMAD').replace(/\bMUHD\b/g,'MOHD').replace(/MOHD\./g,'MOHD').replace(/HAIKAL/g,'HAIQAL').replace(/\bB\.?\b/g,'BIN').replace(/[^A-Z0-9 ]+/g,' ').replace(/\s+/g,' ').trim();}
var DEPT={AMRA:1,AMRAH:1,PATROL:1,IKTAR:1,MHKL:1,RT:1,IPHKL:1,WR:1,IUNA:1,IUNB:1,ED:1,UTK:1,GERAKAN:1,KESELAMATAN:1,HOSPITAL:1,KUALA:1,LUMPUR:1,ANGGOTA:1,BARU:1,RADIOTHERAPY:1,RADIOTERAPI:1};
var STOP={BIN:1,BINTI:1,BT:1,BTE:1,MOHD:1,MOHAMAD:1,ABD:1,AB:1,ANAK:1,A:1,L:1,PB:1,KP:1,KPL:1,SJN:1};
function cleanName(n){var a=U(n).split(' ');while(a.length&&DEPT[a[a.length-1]])a.pop();return a.join(' ');}
function sig(n){return cleanName(n).split(' ').filter(function(w){return w.length>=3&&!STOP[w]&&!DEPT[w];});}
function score(a,b){var A=cleanName(a),B=cleanName(b);if(!A||!B)return 0;if(A===B)return 100;if(A.indexOf(B)>=0||B.indexOf(A)>=0)return 96;var aw=sig(A),bw=sig(B);if(!aw.length||!bw.length)return 0;var hit=0;aw.forEach(function(w){if(bw.indexOf(w)>=0)hit++;});var base=Math.round(hit/Math.max(aw.length,bw.length)*100);if(aw[0]&&bw[0]&&aw[0]===bw[0])base+=8;return Math.min(base,100);}
function mins(t){var m=String(t||'').match(/(\d{1,2}):(\d{2})/);return m?(+m[1])*60+(+m[2]):null;}
function inWin(times,a,b){return (times||[]).filter(function(t){var x=mins(t);return x!=null&&x>=a&&x<=b;});}
function nearest(times,target){var arr=(times||[]).filter(function(t){return mins(t)!=null;});if(!arr.length)return '';return arr.slice().sort(function(a,b){return Math.abs(mins(a)-target)-Math.abs(mins(b)-target);})[0];}
function sh(bil,d){try{var s=(typeof gSh==='function')?gSh(bil,d):'';s=U(s);if(/MALAM|\bM\b|NIGHT/.test(s))return 'M';if(/PETANG|\bPT\b|\bP\b/.test(s))return 'PT';if(/PAGI|\bPG\b|SIANG|\bS\b/.test(s))return 'PG';if(/OFF|OF|REHAT/.test(s))return 'OF';return s;}catch(e){return '';}}
function pair(member,d,today,next){today=today||[];next=next||[];var code=sh(member.bil,d),inn='',out='',note='';if(code==='M'){inn=inWin(today,22*60,23*60+5)[0]||nearest(inWin(today,21*60+30,23*60+59),23*60)||nearest(today,23*60);out=inWin(next,7*60,8*60)[0]||nearest(inWin(next,6*60+30,8*60+30),7*60);note='SHIFT M (2200-2305 / OUT 0700-0800 next day)';}else if(code==='PT'){inn=inWin(today,14*60,15*60+5)[0]||nearest(inWin(today,13*60+30,15*60+30),15*60)||nearest(today,15*60);out=inWin(today,23*60,23*60+59)[0]||nearest(inWin(today,22*60+30,23*60+59),23*60)||((today||[]).length?today[today.length-1]:'');note='SHIFT PT (1400-1505 / OUT 2300-0000)';}else if(code==='PG'){inn=inWin(today,6*60,7*60+5)[0]||nearest(inWin(today,5*60+30,7*60+30),7*60)||((today||[])[0]||'');out=inWin(today,15*60,16*60)[0]||nearest(inWin(today,14*60+30,16*60+30),15*60)||((today||[]).length?today[today.length-1]:'');note='SHIFT PG (0600-0705 / OUT 1500-1600)';}else{inn=(today||[])[0]||'';out=(today||[]).length>1?today[today.length-1]:'';note='NO SHIFT MATCH / RAW';}return {inn:inn,out:out,shift:note,code:code||''};}
function ensureD(b,d){if(typeof D==='undefined'){alert('D/Master data tidak wujud. Buka page e-AKHA Master File dahulu.');throw new Error('D not found');}if(!D[b])D[b]={};if(!D[b][d])D[b][d]={};return D[b][d];}
function runImport(){
  if(typeof MASTER==='undefined'||!Array.isArray(MASTER)){alert('MASTER list tidak wujud. Buka Master File dahulu, kemudian run semula.');return;}
  if(typeof D==='undefined'){alert('D tidak wujud. Buka Master File dahulu.');return;}
  var matched=[],unmatched=[],used={};
  MASTER.forEach(function(m){var best=null,bs=0;TC_DATA.forEach(function(tc,idx){var sc=score(m.nama,tc.n);if(sc>bs){bs=sc;best={tc:tc,idx:idx,score:sc};}});if(best&&best.score>=76){matched.push({m:m,tc:best.tc,idx:best.idx,score:best.score});used[best.idx]=1;}else unmatched.push({bil:m.bil,nama:m.nama,best:best?best.tc.n:'',score:best?best.score:0});});
  var totalPunch=0,totalCells=0,applied=0;
  matched.forEach(function(x){var days=x.tc.d||{};Object.keys(days).forEach(function(ds){var d=+ds;if(d<1||d>30)return;var today=(days[ds]&&days[ds].times)||[];var next=(days[String(d+1)]&&days[String(d+1)].times)||[];if(!today.length&&!next.length)return;var p=pair(x.m,d,today,next);var c=ensureD(x.m.bil,d);c.tc_all=today.slice();c.tc_in=p.inn||'';c.tc_out=p.out||'';c.tc_shift=p.shift;c.tc_src='TC_REBUILD_BY_NAME_APRIL_2026';c.tc_user_id=x.tc.id;c.tc_name_source=x.tc.n;c.tc_match_score=x.score;c.tc_audit_done=false;c.audit_rule_version='TC_REBUILD_NAME_ONLY';totalPunch+=today.length;if(today.length||p.inn||p.out){totalCells++;applied++;}});});
  try{localStorage.setItem('eakha_backup_before_tc_rebuild_'+Date.now(),JSON.stringify(D));}catch(e){}
  try{localStorage.setItem('eakha_data',JSON.stringify(D));localStorage.setItem('eakha_dataset_2026_4',JSON.stringify({tahun:2026,bulan:4,savedAt:new Date().toISOString(),reason:'TC REBUILD BY NAME ONLY APRIL 2026',D:D}));localStorage.setItem('eakha_last_dataset_key','eakha_dataset_2026_4');}catch(e){console.warn(e);}
  try{if(typeof saveDataset==='function')saveDataset('TC REBUILD BY NAME ONLY APRIL 2026');}catch(e){}
  try{if(typeof renderMaster==='function')renderMaster(null);if(typeof renderDash==='function')renderDash();if(typeof updFlags==='function')updFlags();}catch(e){}
  var report={patch:PATCH,matched:matched.map(function(x){return {bil:x.m.bil,master:x.m.nama,tc:x.tc.n,user_id:x.tc.id,score:x.score};}),unmatched:unmatched,totalPunch:totalPunch,totalCells:totalCells,applied:applied,sourceRecords:TC_DATA.length};
  window.TC_REBUILD_REPORT_APRIL_2026=report;
  console.log('TC_REBUILD_REPORT_APRIL_2026',report);console.table(report.matched);if(report.unmatched.length)console.table(report.unmatched);
  alert('TC rebuild BY NAME siap. Matched '+matched.length+'/'+MASTER.length+' anggota. TC cells '+totalCells+' | punches '+totalPunch+'. Semak Master File dahulu, JANGAN Simpan Snapshot jika ada salah.');
}
window.eakhaTCRebuildByNameApril2026=runImport;
if(confirm('Import semula TIMECARD April 2026 ikut NAMA sahaja? Department akan DIABAIKAN. Data KZ/MC/HRMIS tidak disentuh.'))runImport();
})();
